Below is a **complete, single‑file example** that shows how an ASP.NET Core Minimal API can be built in C#.  
It covers:

| Feature | What you’ll see |
|---------|-----------------|
| **Routing** – `MapGet`, `MapPost`, `MapPut`, `MapDelete` |
| **Route groups & tags** – to keep the code tidy |
| **Dependency‑injection** – an in‑memory repository |
| **DTOs** – clear separation between what the API exposes and the domain model |
| **Swagger / OpenAPI** – automatically generated docs |
| **Error handling** – `NotFound`, `Created`, `NoContent`, etc. |

> **Tip** – The code below targets .NET 6/7, but it works unchanged on .NET 8+.  
> Put the code in a single `Program.cs` file and run `dotnet run`.

```csharp
// ---------------------------------------------------------------
// Program.cs
// ---------------------------------------------------------------
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.OpenApi.Models;
using System.Collections.Concurrent;
using System.ComponentModel.DataAnnotations;

var builder = WebApplication.CreateBuilder(args);

// ---------- Services -------------------------------------------------
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen(c =>
{
    c.SwaggerDoc("v1",
        new OpenApiInfo { Title = "Minimal API Demo", Version = "v1" });
});
builder.Services.AddSingleton<IBookRepository, InMemoryBookRepository>();

var app = builder.Build();

// ---------- Middleware ------------------------------------------------
if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI();
}

// ---------- Root endpoint ---------------------------------------------
app.MapGet("/", () => Results.Ok("Welcome to the Minimal API Demo!"))
   .WithName("Root");

// ---------- Book endpoints ---------------------------------------------
var books = app.MapGroup("/books")
              .WithTags("Books");

books.MapGet("/", async (IBookRepository repo) =>
{
    var all = await repo.GetAllAsync();
    return Results.Ok(all);
})
     .WithName("GetAllBooks")
     .Produces<IEnumerable<BookDto>>(StatusCodes.Status200OK);

books.MapGet("/{id:guid}", async (Guid id, IBookRepository repo) =>
{
    var book = await repo.GetByIdAsync(id);
    return book is not null ? Results.Ok(book) : Results.NotFound();
})
     .WithName("GetBookById")
     .Produces<BookDto>(StatusCodes.Status200OK)
     .Produces(StatusCodes.Status404NotFound);

books.MapPost("/", async (BookCreateDto dto, IBookRepository repo) =>
{
    var book = new Book
    {
        Id = Guid.NewGuid(),
        Title = dto.Title,
        Author = dto.Author,
        PublishedDate = dto.PublishedDate
    };

    await repo.AddAsync(book);
    return Results.Created($"/books/{book.Id}", book);
})
     .WithName("CreateBook")
     .Produces<Book>(StatusCodes.Status201Created);

books.MapPut("/{id:guid}", async (Guid id, BookUpdateDto dto, IBookRepository repo) =>
{
    var existing = await repo.GetByIdAsync(id);
    if (existing is null) return Results.NotFound();

    existing.Title = dto.Title;
    existing.Author = dto.Author;
    existing.PublishedDate = dto.PublishedDate;

    await repo.UpdateAsync(existing);
    return Results.NoContent();
})
     .WithName("UpdateBook")
     .Produces(StatusCodes.Status204NoContent)
     .Produces(StatusCodes.Status404NotFound);

books.MapDelete("/{id:guid}", async (Guid id, IBookRepository repo) =>
{
    var removed = await repo.DeleteAsync(id);
    return removed ? Results.NoContent() : Results.NotFound();
})
     .WithName("DeleteBook")
     .Produces(StatusCodes.Status204NoContent)
     .Produces(StatusCodes.Status404NotFound);

// ---------- Run -------------------------------------------------------
app.Run();

// ---------------------------------------------------------------
// Domain & Repository --------------------------------------------
// ---------------------------------------------------------------
public record Book
{
    public Guid Id { get; init; } = Guid.Empty;
    [Required] public string Title { get; set; } = string.Empty;
    [Required] public string Author { get; set; } = string.Empty;
    public DateTime PublishedDate { get; set; }
}

public record BookDto
{
    public Guid Id { get; init; }
    public string Title { get; init; } = string.Empty;
    public string Author { get; init; } = string.Empty;
    public DateTime PublishedDate { get; init; }
}

public record BookCreateDto([Required] string Title,
                            [Required] string Author,
                            DateTime PublishedDate);

public record BookUpdateDto([Required] string Title,
                            [Required] string Author,
                            DateTime PublishedDate);

public interface IBookRepository
{
    Task<IEnumerable<BookDto>> GetAllAsync();
    Task<BookDto?> GetByIdAsync(Guid id);
    Task AddAsync(Book book);
    Task UpdateAsync(Book book);
    Task<bool> DeleteAsync(Guid id);
}

// Simple thread‑safe in‑memory implementation
public class InMemoryBookRepository : IBookRepository
{
    // ConcurrentDictionary gives us a quick, thread‑safe store
    private readonly ConcurrentDictionary<Guid, Book> _store = new();

    public Task<IEnumerable<BookDto>> GetAllAsync()
        => Task.FromResult<IEnumerable<BookDto>>(
            _store.Values.Select(b => ConvertToDto(b)));

    public Task<BookDto?> GetByIdAsync(Guid id)
    {
        return Task.FromResult(_store.TryGetValue(id, out var book)
            ? ConvertToDto(book)
            : null);
    }

    public Task AddAsync(Book book)
    {
        _store[book.Id] = book;
        return Task.CompletedTask;
    }

    public Task UpdateAsync(Book book)
    {
        _store[book.Id] = book;   // Replace existing
        return Task.CompletedTask;
    }

    public Task<bool> DeleteAsync(Guid id)
    {
        return Task.FromResult(_store.TryRemove(id, out _));
    }

    private static BookDto ConvertToDto(Book b) =>
        new(b.Id, b.Title, b.Author, b.PublishedDate);
}
```

### How to test it

1. **Run the application**

   ```bash
   dotnet run
   ```

2. **Open Swagger**

   Navigate to `https://localhost:{port}/swagger`.  
   You’ll see all the endpoints (`GET /books`, `POST /books`, …) automatically documented.

3. **Sample curl commands**

   ```bash
   # Create a new book
   curl -X POST "https://localhost:{port}/books" \
        -H "Content-Type: application/json" \
        -d '{"title":"The Pragmatic Programmer","author":"Andrew Hunt","publishedDate":"1999-10-30"}' \
        -k

   # Get all books
   curl https://localhost:{port}/books -k
   ```

---

This example demonstrates the core of a Minimal API: **compact, strongly‑typed, and fully documented code** with no controller classes or Razor pages.  
You can expand it by adding authentication, validation, paging, or even a real database provider. Happy coding!
